function Get-CodexForgeCurrentReleaseGateStatusLabel {
  param([string]$Status)

  switch ($Status) {
    "PASS" { return "PASS" }
    "MISSING_OPTIONAL" { return "SKIP" }
    "MISSING_REQUIRED" { return "FAIL" }
    "FAILED" { return "FAIL" }
    default { return "NOT_RUN" }
  }
}

